mapper.select:
select a.location_id as locationId,b.area_id as areaId, count(a.id) as totalNum,sum(COALESCE(a.hidden_num,0)) as
hiddenDangerNum,sum(COALESCE(a.hidden_is_done,0)) as hiddenDangerDisposeNum, b.patrol_location_name as locationName
from patrol_task_location a
left join patrol_location b on a.location_id = b.id


        a.start_date >= #{param.period.begin}


        and a.start_date <= #{param.period.end}


        and b.area_id like concat('%',#{param.areaId},'%')


        and b.patrol_location_name like concat('%',#{param.keyword},'%')


GROUP BY a.location_id,b.patrol_location_name,b.area_id order by totalNum desc;

select a.location_id, count(a.id) as totalNum,sum(COALESCE(a.hidden_num,0)) as hiddenDangerNum,sum(COALESCE(a.hidden_is_done,0)) as
hiddenDangerDisposeNum, b.patrol_location_name as locationName
from patrol_task_location a
left join patrol_location b on a.location_id = b.id


        a.start_date >= #{param.period.begin}


        and a.start_date <= #{param.period.end}


        and a.result = #{param.result}


GROUP BY a.location_id,b.patrol_location_name order by totalNum;

select a.user_id, count(a.id) as totalNum, count(DISTINCT b.id) as taskNum
from patrol_task_location a
left join patrol_task b on a.task_id = b.id

    a.user_id is not null

        and a.start_date >= #{param.period.begin}


        and a.start_date <= #{param.period.end}


        and b.user_dep_id = #{param.depId}


        and b.user_name like concat('%',#{param.keyword},'%')


        and b.id in

            #{taskId}



GROUP BY a.user_id order by totalNum;

select a.user_id, count(a.id) as totalNum, count(DISTINCT b.id) as taskNum
from patrol_task_location a
left join patrol_task b on a.task_id = b.id

    a.user_id is not null

        and a.start_date >= #{param.period.begin}


        and a.start_date <= #{param.period.end}


        and b.user_dep_id = #{param.depId}


        and b.user_name like concat('%',#{param.keyword},'%')


        and b.id in

            #{taskId}



GROUP BY a.user_id order by totalNum;

select b.*
from patrol_task b
left join patrol_task_location a on a.task_id = b.id
where a.location_id = #{locationId}
and b.status = #{status}
order by b.start_date desc

SELECT a.locationName locationName, a.locationId locationId, a.totalNum totalNum, b.abnormal abnormalNum, c.num realNum FROM ( SELECT a.location_id AS locationId, count( a.id ) AS totalNum, b.patrol_location_name AS locationName FROM patrol_task_location a LEFT JOIN patrol_location b ON a.location_id = b.id where a.deleted = 0
and a.start_date >= #{param.period.begin}
and a.start_date <= #{param.period.end}
GROUP BY b.patrol_location_name, a.location_id ) a LEFT JOIN ( SELECT location_id, COUNT( id ) AS abnormal FROM patrol_task_location WHERE result = 'ABNORMAL'
and start_date >= #{param.period.begin}
and start_date <= #{param.period.end}
group by location_id ) b ON a.locationId = b.location_id LEFT JOIN ( SELECT location_id, COUNT( id ) AS num FROM patrol_task_location WHERE patrol_date IS NOT NULL
and patrol_date >= #{param.period.begin}
and patrol_date <= #{param.period.end}
group by location_id ) c ON a.locationId = c.location_id order by abnormalNum DESC limit 5

select l.location_id as locationId,p.patrol_location_name as locationName,count(l.id) as omitNum
from patrol_task_location l
left join patrol_location p on l.location_id = p.id
where l.deleted = 0

    and l.start_date >= #{param.period.begin}


    and l.start_date <= #{param.period.end}


    and l.exception_type = #{param.exceptionType}

group by l.location_id order by omitNum desc

select ptl.location_id as locationId, pl.patrol_location_name as locationName, count(ptl.id) as num from patrol_task_location ptl left join patrol_location pl on ptl.location_id = pl.id where ptl.result = 'ABNORMAL'
and ptl.start_date between #{period.begin,jdbcType=TIMESTAMP} and #{period.end,jdbcType=TIMESTAMP}
group by ptl.location_id order by num desc limit 5

select ptl.location_id as locationId, pl.patrol_location_name as locationName, count(ptl.id) as num from patrol_task_location ptl left join patrol_location pl on ptl.location_id = pl.id where ptl.result = 'ABNORMAL' and exception_type = 'LEAK_DETECTION'
and ptl.start_date between #{period.begin,jdbcType=TIMESTAMP} and #{period.end,jdbcType=TIMESTAMP}
group by ptl.location_id order by num desc limit 5

SELECT count(a.id)
FROM patrol_task_location a
WHERE a.start_date between #{period.begin,jdbcType=TIMESTAMP} and #{period.end,jdbcType=TIMESTAMP}

select patrol_route_name, b.number as patrolLocationNumber,c.id,c.result from patrol_task a inner join patrol_route b on a.route_id = b.uuid inner join patrol_task_location c on a.id=c.task_id
c.patrol_date between #{param.period.begin} and #{param.period.end}
and patrol_route_name like CONCAT('%',#{param.keyword},'%')

SELECT pt.`status`, COUNT( pt.id ) as num FROM patrol_task pt
and pt.create_time >= #{period.begin}
and pt.create_time <= #{period.end}
GROUP BY pt.`status`

select ptl.task_id as "key", count(1) as "value"
from patrol_task_location ptl
where ptl.superintendent_user_id = #{userId}

    and ptl.result is null


    and ptl.task_id in

        #{taskId}


group by ptl.task_id;
